/**
 * MECHPLANT — KaTeX Auto-Render Extension (Compatible con KaTeX v0.16.11 y katex-offline-fallback.js)
 * Ruta: assets/js/vendor/katex/auto-render.min.js
 * Expone window.renderMathInElement(elem, options) para detectar y compilar
 * delimitadores LaTeX ($$...$$, \[...\], $...$, \(...\)) en cualquier nodo del DOM.
 */
(function (global) {
  "use strict";

  const DEFAULT_OPTIONS = {
    delimiters: [
      { left: "$$", right: "$$", display: true },
      { left: "\\[", right: "\\]", display: true },
      { left: "$", right: "$", display: false },
      { left: "\\(", right: "\\)", display: false }
    ],
    ignoredTags: ["script", "noscript", "style", "textarea", "pre", "code", "option"],
    ignoredClasses: ["katex", "katex-display", "no-math"],
    throwOnError: false,
    errorCallback: console.error
  };

  function findEndOfMath(delimiter, text, startIndex) {
    let index = startIndex;
    const delimLen = delimiter.length;

    while (index < text.length) {
      const char = text[index];
      if (char === "\\") {
        // Salta caracteres escapados (ej. \$)
        index += 2;
        continue;
      }
      if (text.startsWith(delimiter, index)) {
        return index;
      }
      index++;
    }
    return -1;
  }

  function splitAtDelimiters(text, delimiters) {
    const data = [];
    let remaining = text;

    while (remaining.length > 0) {
      let earliestMatch = null;

      for (let i = 0; i < delimiters.length; i++) {
        const delim = delimiters[i];
        let searchFrom = 0;

        while (searchFrom < remaining.length) {
          const leftIdx = remaining.indexOf(delim.left, searchFrom);
          if (leftIdx === -1) break;

          // Ignora delimitador escapado con barra invertida
          if (leftIdx > 0 && remaining[leftIdx - 1] === "\\") {
            searchFrom = leftIdx + delim.left.length;
            continue;
          }

          // Para $ simple, evita falsos positivos en precios como "$ 50" o "$100" sin cierre
          if (delim.left === "$") {
            const nextChar = remaining[leftIdx + 1];
            if (!nextChar || /\s/.test(nextChar)) {
              searchFrom = leftIdx + 1;
              continue;
            }
          }

          const contentStart = leftIdx + delim.left.length;
          const rightIdx = findEndOfMath(delim.right, remaining, contentStart);

          if (rightIdx !== -1) {
            if (delim.right === "$") {
              const prevChar = remaining[rightIdx - 1];
              if (!prevChar || /\s/.test(prevChar)) {
                searchFrom = leftIdx + 1;
                continue;
              }
            }

            if (!earliestMatch || leftIdx < earliestMatch.leftIdx) {
              earliestMatch = {
                leftIdx,
                rightIdx,
                delim
              };
            }
            break;
          }

          searchFrom = leftIdx + delim.left.length;
        }
      }

      if (!earliestMatch) {
        data.push({ type: "text", data: remaining });
        break;
      }

      if (earliestMatch.leftIdx > 0) {
        data.push({
          type: "text",
          data: remaining.slice(0, earliestMatch.leftIdx)
        });
      }

      const mathContent = remaining.slice(
        earliestMatch.leftIdx + earliestMatch.delim.left.length,
        earliestMatch.rightIdx
      );

      data.push({
        type: "math",
        data: mathContent,
        rawData: remaining.slice(
          earliestMatch.leftIdx,
          earliestMatch.rightIdx + earliestMatch.delim.right.length
        ),
        display: Boolean(earliestMatch.delim.display)
      });

      remaining = remaining.slice(earliestMatch.rightIdx + earliestMatch.delim.right.length);
    }

    return data;
  }

  function hasIgnoredClass(element, ignoredClasses) {
    if (!element || !element.classList) return false;
    for (let i = 0; i < ignoredClasses.length; i++) {
      if (element.classList.contains(ignoredClasses[i])) return true;
    }
    return false;
  }

  function renderElem(elem, options) {
    const childNodes = Array.from(elem.childNodes);

    for (let i = 0; i < childNodes.length; i++) {
      const child = childNodes[i];

      if (child.nodeType === Node.TEXT_NODE) {
        const text = child.textContent;
        if (!text || !text.trim()) continue;

        const segments = splitAtDelimiters(text, options.delimiters);
        if (segments.length === 1 && segments[0].type === "text") {
          continue;
        }

        const fragment = document.createDocumentFragment();
        for (let j = 0; j < segments.length; j++) {
          const seg = segments[j];
          if (seg.type === "text") {
            fragment.appendChild(document.createTextNode(seg.data));
          } else {
            const span = document.createElement("span");
            try {
              global.katex.render(seg.data, span, {
                displayMode: seg.display,
                throwOnError: options.throwOnError
              });
            } catch (err) {
              if (options.throwOnError) throw err;
              options.errorCallback("KaTeX auto-render error:", err);
              span.textContent = seg.rawData;
            }
            fragment.appendChild(span);
          }
        }

        elem.replaceChild(fragment, child);
      } else if (child.nodeType === Node.ELEMENT_NODE) {
        const tagName = child.nodeName.toLowerCase();
        const isIgnoredTag = options.ignoredTags.indexOf(tagName) !== -1;
        const isIgnoredClass = hasIgnoredClass(child, options.ignoredClasses);

        if (!isIgnoredTag && !isIgnoredClass) {
          renderElem(child, options);
        }
      }
    }
  }

  function renderMathInElement(elem, customOptions = {}) {
    if (!elem) {
      throw new Error("renderMathInElement requiere un elemento DOM válido.");
    }
    if (!global.katex || typeof global.katex.render !== "function") {
      console.warn("[auto-render] window.katex no está disponible todavía.");
      return;
    }

    const options = {
      delimiters: customOptions.delimiters || DEFAULT_OPTIONS.delimiters,
      ignoredTags: (customOptions.ignoredTags || DEFAULT_OPTIONS.ignoredTags).map((t) =>
        t.toLowerCase()
      ),
      ignoredClasses: customOptions.ignoredClasses || DEFAULT_OPTIONS.ignoredClasses,
      throwOnError:
        customOptions.throwOnError !== undefined
          ? customOptions.throwOnError
          : DEFAULT_OPTIONS.throwOnError,
      errorCallback: customOptions.errorCallback || DEFAULT_OPTIONS.errorCallback
    };

    renderElem(elem, options);
  }

  global.renderMathInElement = renderMathInElement;
})(typeof window !== "undefined" ? window : this);
